#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <iostream>
#include <type_traits>
#include <vector>

// variant spec: channel (y/u/v), mask bits d0,d1,d2 (constant is double), grouping g in {0,1,2}
// grouping 0: (t0+t1)+t2   1: (t0+t2)+t1   2: (t1+t2)+t0
// t0 = c0*r, t1 = c1*g, t2 = c2*b  (signs folded into constants; a-b == a+(-b) exactly)

template <bool D0, bool D1, bool D2, int G>
static float compute(double K0, double K1, double K2, float r, float g, float b) {
    using T0 = std::conditional_t<D0, double, float>;
    using T1 = std::conditional_t<D1, double, float>;
    using T2 = std::conditional_t<D2, double, float>;
    T0 c0 = (T0)K0;
    T1 c1 = (T1)K1;
    T2 c2 = (T2)K2;
    auto t0 = c0 * r;
    auto t1 = c1 * g;
    auto t2 = c2 * b;
    if (G == 0) { auto s = t0 + t1; auto s2 = s + t2; return (float)s2; }
    if (G == 1) { auto s = t0 + t2; auto s2 = s + t1; return (float)s2; }
    { auto s = t1 + t2; auto s2 = s + t0; return (float)s2; }
}

typedef float (*Fn)(double,double,double,float,float,float);

template <int M, int G> struct Inst {
    static float call(double a,double b_,double c,float r,float g,float b) {
        return compute<(bool)(M&1),(bool)(M&2),(bool)(M&4),G>(a,b_,c,r,g,b);
    }
};

static Fn table[8][3];
template <int M> static void fill() {
    table[M][0] = &Inst<M,0>::call;
    table[M][1] = &Inst<M,1>::call;
    table[M][2] = &Inst<M,2>::call;
}
static void init() {
    fill<0>(); fill<1>(); fill<2>(); fill<3>(); fill<4>(); fill<5>(); fill<6>(); fill<7>();
}

int main(int argc, char** argv) {
    init();
    // argv[1] = channel: y|u|v ; argv[2] = mask 0..7 ; argv[3] = grouping 0..2
    // argv[4..] optional constant overrides
    char ch = argv[1][0];
    int mask = atoi(argv[2]);
    int grp  = atoi(argv[3]);
    double K0,K1,K2;
    if (ch=='y') { K0=0.299; K1=0.587; K2=0.114; }
    else if (ch=='u') { K0=-0.147; K1=-0.289; K2=0.436; }
    else { K0=0.615; K1=-0.515; K2=-0.100; }
    if (argc>6) { K0=atof(argv[4]); K1=atof(argv[5]); K2=atof(argv[6]); }
    Fn f = table[mask][grp];
    std::string sr, sg, sb;
    while (std::cin >> sr >> sg >> sb) {
        float r = std::stof(sr), g = std::stof(sg), b = std::stof(sb);
        float out = f(K0,K1,K2,r,g,b);
        std::cout << out << "\n";
    }
    return 0;
}
