#include <cstdio>
#include <cstdint>
#include <cmath>
#include <cstdlib>
#include <cstring>
// PRNG
static uint64_t s_=0x123456789abcdefULL;
static uint64_t nx(){ s_^=s_<<13; s_^=s_>>7; s_^=s_<<17; return s_; }
static double u01(){ return (double)(nx()>>11) / 9007199254740992.0; }
static float clampf(double v){ if(!(v>-1e30&&v<1e30)) return 0.5f; return (float)v; }
static void emit(float r,float g,float b){
    // avoid subnormal / zero-underflow strings for stof; snap tiny to 0
    auto fix=[](float x)->float{ if (std::fabs(x) < 1e-30f) return 0.0f; return x; };
    r=fix(r);g=fix(g);b=fix(b);
    printf("%.9g %.9g %.9g\n",(double)r,(double)g,(double)b);
}
int main(int argc,char**argv){
    long n = atol(argv[1]);
    unsigned mode = argc>2?atoi(argv[2]):0;
    if (argc>3) s_ = strtoull(argv[3],0,10)|1;
    for(long i=0;i<n;i++){
        unsigned m = (mode==0)? (nx()%7) : mode-1;
        double r,g,b;
        if(m==0){ r=u01()*2-1; g=u01()*2-1; b=u01()*2-1; }
        else if(m==1){ r=u01(); g=u01(); b=u01(); }
        else if(m==2){ // v ~ 0 cancellation
            r=u01()*2-1; g=u01()*2-1; b=(0.615*r-0.515*g)/0.1; if(fabs(b)>1e6){i--;continue;} }
        else if(m==3){ // u ~ 0
            r=u01()*2-1; g=u01()*2-1; b=(0.147*r+0.289*g)/0.436; }
        else if(m==4){ // y ~ 0
            r=u01()*2-1; g=u01()*2-1; b=-(0.299*r+0.587*g)/0.114; if(fabs(b)>1e6){i--;continue;} }
        else if(m==5){ // wide dynamic range
            double e1=u01()*30-15,e2=u01()*30-15,e3=u01()*30-15;
            r=(u01()*2-1)*pow(2.0,e1); g=(u01()*2-1)*pow(2.0,e2); b=(u01()*2-1)*pow(2.0,e3); }
        else { // near-integer-ish / short decimals
            r=(double)(int)(u01()*2001-1000)/1000.0;
            g=(double)(int)(u01()*2001-1000)/1000.0;
            b=(double)(int)(u01()*2001-1000)/1000.0; }
        emit(clampf(r),clampf(g),clampf(b));
    }
    return 0;
}
